// 버전5(실험) 나무 데이터 — 픽셀아트(포켓몬 스타일). 버전3(TreeSceneV3.jsx)와 같은
// 방식(가지만 있는 나무 사진을 격자로 스캔해 실제 가지 픽셀만 앵커로 씀, 몸통·뿌리
// 제외, 잎마다 줄기 방향을 감지해 가지 각도에 맞춰 회전)을 그대로 따름. v2/v3/v4와
// 완전히 분리된 파일이라 이 파일을 고쳐도 다른 버전에는 영향 없음.

function seededRandom(seed) {
  let s = seed | 0;
  return function () {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffledAnchors(list) {
  const arr = [...list];
  const rand = seededRandom(20260921);
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// 잔가지(thin/앞) 앵커가 중간 굵기(medium/뒤) 앵커보다 훨씬 적어서(약 1:28) 그냥 합쳐서
// 섞으면 실제 점수만큼 자랄 때 잔가지 쪽이 한참 뒤에나 채워져서 가지 끝부분이 휑해
// 보임 — medium THIN_RATIO개마다 thin 하나씩 끼워 넣어서(짧은 쪽은 돌려씀) 나무가
// 자라는 동안 잔가지 앞쪽도 항상 고르게 같이 채워지도록 함
function interleaveByTier(thin, medium) {
  const thinShuffled = shuffledAnchors(thin);
  const medShuffled = shuffledAnchors(medium);
  const THIN_RATIO = 4;
  const result = [];
  for (let i = 0; i < medShuffled.length; i++) {
    result.push(medShuffled[i]);
    if (i % THIN_RATIO === THIN_RATIO - 1) {
      result.push(thinShuffled[Math.floor(i / THIN_RATIO) % thinShuffled.length]);
    }
  }
  return result;
}

// tree-bare-pixel.png 원본 픽셀 크기와, 그 사진을 SVG 로컬 좌표(GROUND_ANCHOR=(120,232)
// 기준)에 배치하는 스케일/오프셋. 트렁크 밑동 픽셀(668,1245)을 GROUND_ANCHOR에 맞춤.
const TREE_PHOTO_W = 1254;
const TREE_PHOTO_H = 1254;
const TREE_PHOTO_SCALE = 0.1841;
const TREE_PHOTO_OFFSET_X = 120 - 668 * TREE_PHOTO_SCALE;
const TREE_PHOTO_OFFSET_Y = 232 - 1245 * TREE_PHOTO_SCALE;

export const TREE_V5_IMAGE = {
  src: '/images/v5-pixel/tree-bare-pixel2.png',
  x: TREE_PHOTO_OFFSET_X,
  y: TREE_PHOTO_OFFSET_Y,
  width: TREE_PHOTO_W * TREE_PHOTO_SCALE,
  height: TREE_PHOTO_H * TREE_PHOTO_SCALE,
};

function photoToSvg(px, py) {
  return { x: TREE_PHOTO_OFFSET_X + px * TREE_PHOTO_SCALE, y: TREE_PHOTO_OFFSET_Y + py * TREE_PHOTO_SCALE };
}

